            if len(required[i]) == 2:
                required[i] = {'0', '1'}
            elif len(required[i]) == 0:
                possible = False
                break

        if not possible:
            print("NO")
            continue

        # Build the lex smallest string
        res = []
        for i in range(k):
            if '0' in required[i]:
                res.append('0')
            else:
                res.append('1')
